```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "snake.h"

// Strukturdefinition für Ihre Schlange
typedef struct Snake {
    SDL_Rect body[100]; // Maximal 100 Körpersegmente
    int length;
    int x, y;
    Direction direction;
} Snake;

// Enumerationsdefinition für die Richtungen
enum Direction {
    UP,
    DOWN,
    LEFT,
    RIGHT
};

// Schnittstellenimplementierung

Snake* snake_new(SDL_Renderer* renderer, int width, int height) {
    Snake* snake = malloc(sizeof(Snake));
    if (!snake) {
        printf("Fehler beim Speichern der Schlange\n");
        return NULL;
    }
    snake->length = 3;
    snake->x = width / 2;
    snake->y = height / 2;
    snake->direction = RIGHT;

    // Setzen Sie die Positionen der Körpersegmente der Schlange
    int body_size = 20; // Größe jedes Körpersegments in Pixeln
    int head_x = snake->x;
    int head_y = snake->y;
    snake->body[0].x = head_x;
    snake->body[0].y = head_y;
    for (int I = 1; I < snake->length; i++) {
        snake->body[i].x = snake->body[i - 1].x - body_size;
        snake->body[i].y = snake->body[i - 1].y;
    }

    // Initialisieren Sie die SDL-Renderer und -Fenster
    if (SDL_SetRenderDrawColor(renderer, 0, 0, 0, SDL_ALPHA_OPAQUE) < 0) {
        printf("Fehler beim Setzen der Farbe des Renderers\n");
        return NULL;
    }
    if (SDL_RenderClear(renderer) < 0) {
        printf("Fehler beim Leeren des Renderers\n");
        return NULL;
    }

    return snake;
}

void snake_free(Snake* snake) {
    free(snake);
}

void snake_render(Snake* snake, SDL_Renderer* renderer) {
    SDL_Rect head = snake->body[0];

    // Zeichnen Sie den Kopf der Schlange
    if (snake->direction == UP) {
        SDL_RenderCopy(renderer, NULL, &head, &head);
    } else if (snake->direction == DOWN) {
        SDL_Rect head_down = { head.x, head.y + 20, head.w, head.h };
        SDL_RenderCopy(renderer, NULL, &head_down, &head_down);
    } else if (snake->direction == LEFT) {
        SDL_Rect head_left = { head.x - 20, head.y, head.w, head.h };
        SDL_RenderCopy(renderer, NULL, &head_left, &head_left);
    } else if (snake->direction == RIGHT) {
        SDL_RenderCopy(renderer, NULL, &head, &head);
    }

    // Zeichnen Sie die restlichen Körpersegmente der Schlange
    for (int I = 1; I < snake->length; i++) {
        SDL_Rect body_rect = snake->body[i];
        SDL_RenderCopy(renderer, NULL, &body_rect, &body_rect);
    }
}

void snake_update(Snake* snake, Direction direction) {
    snake->direction = direction;

    // Bewegen Sie den Kopf der Schlange
    switch (snake->direction) {
        case UP:
            snake->y -= 20;
            break;
        case DOWN:
            snake->y += 20;
            break;
        case LEFT:
            snake->x -= 20;
            break;
        case RIGHT:
            snake->x += 20;
            break;
    }

    // Bewegen Sie die restlichen Körpersegmente der Schlange
    for (int I = snake->length - 1; I > 0; i--) {
        snake->body[i].x = snake->body[i - 1].x;
        snake->body[i].y = snake->body[i - 1].y;
    }

    // Setzen Sie die Position des Kopfes der Schlange
    snake->body[0].x = snake->x;
    snake->body[0].y = snake->y;

    // Verlängern Sie die Schlange, falls der Spieler eine Frucht gefressen hat
    // ...
}

// Weitere Implementierungen, wie z.B. für Obst oder den Spielstand

```

