- Hier sind einige Beispiele:

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "snake.h"

// Definieren Sie Konstanten für das Spiel, wie z.B. die Größe des Spielfelds und die Geschwindigkeit
#define FIELD_WIDTH 800
#define FIELD_HEIGHT 600
#define SNAKE_SPEED 200 // in Millisekunden

int main(int argc, char* argv[]) {
    SDL_Init(SDL_INIT_VIDEO);

    SDL_Window* window = SDL_CreateWindow("Snake Game",
                                           SDL_WINDOWPOS_CENTERED, SDL_WINDOWPOS_CENTERED,
                                           FIELD_WIDTH, FIELD_HEIGHT, SDL_WINDOW_SHOWN);

    SDL_Renderer* renderer = SDL_CreateRenderer(window, -1, SDL_RENDERER_ACCELERATED);

    Snake* snake = snake_new(renderer, FIELD_WIDTH, FIELD_HEIGHT);

    // Laden Sie Ihre Bilder, um sie als Texturen zu verwenden
    SDL_Surface* apple_surface = SDL_LoadBMP("images/apple.bmp");
    SDL_Texture* apple_texture = SDL_CreateTextureFromSurface(renderer, apple_surface);
    SDL_FreeSurface(apple_surface);

    SDL_Surface* background_surface = SDL_LoadBMP("images/background.bmp");
    SDL_Texture* background_texture = SDL_CreateTextureFromSurface(renderer, background_surface);
    SDL_FreeSurface(background_surface);

    // Initialisieren Sie die SDL-Renderer und -Fenster
    if (SDL_SetRenderDrawColor(renderer, 0, 0, 0, SDL_ALPHA_OPAQUE) < 0) {
        printf("Fehler beim Setzen der Farbe des Renderers\n");
        return 1;
    }
    if (SDL_RenderClear(renderer) < 0) {
        printf("Fehler beim Leeren des Renderers\n");
        return 1;
    }

    // Spiel-Schleife
    SDL_Event event;
    bool running = true;
    while (running) {
        while (SDL_PollEvent(&event)) {
            if (event.type == SDL_QUIT) {
                running = false;
            } else if (event.type == SDL_KEYDOWN) {
                switch (event.key.keysym.sym) {
                    case SDLK_UP:
                        snake_update(snake, UP);
                        break;
                    case SDLK_DOWN:
                        snake_update(snake, DOWN);
                        break;
                    case SDLK_LEFT:
                        snake_update(snake, LEFT);
                        break;
                    case SDLK_RIGHT:
                        snake_update(snake, RIGHT);
                        break;
                }
            }
        }

        // Animieren Sie das Spiel
        SDL_RenderCopy(renderer, background_texture, NULL, NULL);
        snake_render(snake, renderer);

        // Zeichnen Sie Obst, falls es im Spiel vorhanden ist
        // ...

        SDL_RenderPresent(renderer);
        SDL_Delay(SNAKE_SPEED);

        // Überprüfen Sie, ob die Schlange mit sich selbst kollidiert oder außerhalb des Spielfelds ist
        // ...

        // Überprüfen Sie, ob der Spieler die Frucht gefressen hat
        // ...

        // Aktualisieren Sie den Spielstand
        // ...

    }

    SDL_DestroyTexture(apple_texture);
    SDL_DestroyTexture(background_texture);
    SDL_DestroyRenderer(renderer);
    SDL_DestroyWindow(window);
    SDL_Quit();

    snake_free(snake);

    return 0;
}
```

