```js
// Öffnet den Modal
const openModal = document.getElementById("open-modal");
const modalOverlay = document.getElementById("modal-overlay");
const modal = document.getElementById("modal");

openModal.addEventListener("click", () => {
  modalOverlay.style.display = "flex";
});

// Schließt den Modal
const closeModal = () => {
  modalOverlay.style.display = "none";
};

// Erstellt den Chatverlauf
const chatLog = document.getElementById("chat-log");
let chatHistory = [];

function createChatMessage(className, messageText, timestamp) {
  const messageDiv = document.createElement("div");
  messageDiv.classList.add("chat-message", className);

  const messageTextDiv = document.createElement("div");
  messageTextDiv.classList.add("chat-message__text");
  messageTextDiv.textContent = messageText;

  const timestampDiv = document.createElement("div");
  timestampDiv.classList.add("chat-message__timestamp");
  timestampDiv.textContent = timestamp;

  messageDiv.appendChild(messageTextDiv);
  messageDiv.appendChild(timestampDiv);

  return messageDiv;
}

function addChatMessage(message) {
  chatHistory.push(message);
  chatLog.insertAdjacentElement("beforeend", message);
}

// Fügt Nachrichten zum Chatverlauf hinzu
function simulateChat() {
  // Nachrichten vom Bot
  addChatMessage(createChatMessage("chat-message__bot", "Hallo, wie kann ich dir helfen?", new Date().toISOString()));
  addChatMessage(createChatMessage("chat-message__user", "Ich habe eine Frage zu Ihrem Produkt.", new Date().toISOString()));

  // Nachrichten vom Menschen
  addChatMessage(createChatMessage("chat-message__bot", "Natürlich! Unsere Produktlinie umfasst...", new Date().toISOString()));
  addChatMessage(createChatMessage("chat-message__user", "Könnten Sie mir bitte mehr über das Produkt X erzählen?", new Date().toISOString()));
}

// Sendet eine Nachricht und aktualisiert den Chatverlauf
const chatForm = document.getElementById("chat-form");
chatForm.addEventListener("submit", (event) => {
  event.preventDefault();
  const input = document.getElementById("chat-input");
  const messageText = input.value;
  const timestamp = new Date().toISOString();

  addChatMessage(createChatMessage("chat-message__user", messageText, timestamp));

  input.value = "";

  // Simuliert eine Antwort vom Bot
  setTimeout(() => {
    addChatMessage(createChatMessage("chat-message__bot", "Das Produkt X bietet viele Vorteile, wie...", timestamp));
  }, 1000);
});

// Initialisiere den Chatverlauf
simulateChat();

// Schließt den Modal, wenn der Benutzer auf die Überlagerung klickt
modalOverlay.addEventListener("click", (event) => {
  if (event.target === modalOverlay) {
    closeModal();
  }
});
```

