Hier ist ein C++-Programm, das eine Textdatei Zeile für Zeile liest und die Anzahl der Vorkommen eines bestimmten Wortes in der Datei zählt:

```cpp
#include <iostream>
#include <fstream>
#include <string>

using namespace std;

int main() {
    string wordToCount; // Wort, nach dem gesucht werden soll
    int count = 0; // Anzahl der Vorkommen des Wortes

    // Wort eingeben, nach dem gesucht werden soll
    cout << "Bitte das Wort eingeben, nach dem gesucht werden soll: ";
    cin >> wordToCount;

    // Dateiname eingeben
    string fileName;
    cout << "Bitte den Dateinamen eingeben: ";
    cin >> fileName;

    // Datei öffnen
    ifstream file(fileName);
    if (!file) {
        cerr << "Fehler: Datei konnte nicht geöffnet werden." << endl;
        return 1;
    }

    // Zeile für Zeile lesen und Wort zählen
    string line;
    while (getline(file, line)) {
        size_t pos = 0;
        while ((pos = line.find(wordToCount, pos)) != string::npos) {
            count++; // Wort gefunden, Anzahl erhöhen
            pos += wordToCount.length(); // nächster Suchstartpunkt festlegen
        }
    }

    // Ergebnis ausgeben
    cout << "Das Wort \"" << wordToCount << "\" ist in der Datei " << fileName << " " << count << " Mal vorkommend." << endl;

    // Datei schließen
    file.close();

    return 0;
}
```

